const resolveReport = `-- name: ResolveReport :many
UPDATE community_report SET status = $1, resolved_by = $2, resolved_at = $3
WHERE id = $4 RETURNING id
`

func (q *Queries) ResolveReport(ctx context.Context, status string, resolvedBy *string, now *jsontime.Time, iD string) ([]string, error) {
	rows, err := q.db.Query(ctx, resolveReport,
		status,
		resolvedBy,
		now,
		iD,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

